  phases: [{ title: 'Fix' }, { title: 'Verify' }],
}

const ROOT = args.root
const SCOPE = args.scope
const RESULT = {
  type: 'object',
  properties: {
    ticket: { type: 'string' },
    passed: { type: 'boolean' },
    check: { type: 'string', description: 'the exact command that ran and its result line' },
    why: { type: 'string' },
    files: { type: 'array', items: { type: 'string' } },
  },
  required: ['ticket', 'passed', 'check', 'why', 'files'],
}

const results = await pipeline(
  args.items,
  (it) => agent(
    `Repo: ${ROOT}\n\n${it.prompt}\n\n${SCOPE}\nPut this item's tests in ${it.testFile} (new file, import from shelf; call books.clear() in setup_function). Touch only: ${it.files.join(', ')}. Run \`python -m pytest -q\` from the repo root before you finish and report the result line.`,
    { label: `AAAC fix:${it.ticket}`, phase: 'Fix', schema: RESULT, ...(it.fixModel ? { model: it.fixModel } : {}) }
  ),
  (fix, it) => agent(
    `Repo: ${ROOT}\nIndependently verify ticket ${it.ticket}. Requirement:\n${it.prompt}\n\nThe fixer reported: ${JSON.stringify(fix)}\n\nRead the changed code in ${it.files.join(', ')}, check it actually meets the requirement (edge cases: empty shelf; JSON must parse with json.loads; --version must print exactly "shelf 0.1.0" via python -m shelf --version). Run \`python -m pytest -q\` and the real command where applicable. Do not edit files and do not commit. passed=true only if a check you ran shows it.`,
    { label: `AAAC verify:${it.ticket}`, phase: 'Verify', schema: RESULT }
  )
)
return results

